      "中国模型的爆发始于 2024 年圣诞节 DeepSeek 3 的发布，据称训练成本仅约 550 万美元。随后在 1 月 20 日，DeepSeek 又推出了 R1 模型，直接引发了 AI 及半导体板块的大幅抛售：随着投资者意识到AI 可能并非美国独占领域，英伟达市值单日蒸发约 5,930 亿美元。",
