    "exerciseTranslationPrompt": "据《自然》（Nature）近期发布的报告，在互联网连接、通信服务和地图测绘需求持续扩大的驱动下，地球轨道上的卫星数量正急剧攀升，到 2030 年代末，总数预计将达到 50 万颗。",
