    "exerciseTranslationPrompt": "哈梅内伊（Khamenei）明白，维持权力的最佳方式是在一个封闭的气泡中运作。不是彻底孤立——他仍需出售伊朗的石油——而是经过精心校准的封闭状态，把国家与全球资本主义和公民社会的力量隔绝开来，以免这些力量侵蚀政权。",
