    "folder": "0312 石油危机将如何改变一切？1",
    "titleZh": "石油危机将如何改变一切？1",
    "title": "How an Oil Crisis Becomes an Everything Crisis",
    "topicEn": "Economics",
    "topicZh": "经济",
    "byline": "By Philip Delves Broughton, Bloomberg, Published March 6, 2026",
    "paragraphs": [
      "In October 1973, President Richard Nixon faced an affordability crisis, a worsening economy and mounting legal problems. In the runup to the 1972 election, he had challenged the Federal Reserve's independence and pressured its chair to cut interest rates. Now the bill was coming due in the form of fast-rising inflation.",
      "Then came fresh conflict in the Middle East. Egypt and Syria invaded Israel, launching the Yom Kippur War. The price of oil was already rising sharply when Arab producers imposed an embargo, cutting supplies in protest at US support for Israel.",
      "Nixon found distraction overseas. Before resigning in 1974, he normalized relations with China, relaxed tensions with the Soviet Union, ended America's involvement in the Vietnam War and dispatched Secretary of State Henry Kissinger to keep the peace in the Middle East. Even when Nixon was slumped and slurring in the White House residence — dulled by mood stabilizers, sleeping pills and alcohol — the machinery of American diplomacy kept whirring. Perhaps voters would be so dazzled by his achievements as a statesman that they would overlook the criminality. Ultimately, they weren't. Foreign policy could not salvage his approval ratings, which fell from 68% in January to 30% by October. The outbreak of war in the Middle East led to higher energy prices, weakened the US economy and drained support from an already scandal-plagued administration.",
      "As the world considers the ramifications of the attack by the US and Israel on Iran, it's important to remember the lesson of the 1973 oil shock: An energy crisis can snowball into a wildly unpredictable \"everything crisis\" faster than governments can manage. What began with questions about the flow of oil and gas soon reshaped America's relationship to the world, and reached deep into daily life in ways that no one could have predicted.",
      "Testing Alliances",
      "In 1973, the fast-rising challengers to America's economic supremacy were West Germany and Japan. Suspicions flared that the US had concocted the oil crisis to slow down their booming and increasingly competitive economies. With this week's war coming so soon after the disruption of the Trump administration's signature tariff policy, modern rivals to the US such as China might reasonably wonder the same thing. China relies mostly on coal for its energy, but at least 6% of its total energy imports passes through the Strait of Hormuz as crude oil — enough to cause concern if the war goes on for months rather than weeks.",
      "Europe will also find itself squeezed. The Trump administration has repeatedly assailed NATO allies over defense spending, Greenland and trade. Now the president is berating individual European countries for not supporting the attack on Iran. Spain has been labeled \"uncooperative\" for refusing US access to its military bases in the country. The UK has failed to live up to the memory of Winston Churchill. Even though the Middle East accounts for only 5% of Europe's total crude imports, an across-the-board price rise will hurt. The continent's economies are already struggling with record debts and the threat of inflation. Whatever was left of the transatlantic alliance is being tested yet again.",
      "Kissinger had declared 1973 the \"Year of Europe\" to try to repair a relationship that had soured. But in private he and Nixon spoke scathingly of the Europeans' treachery and spinelessness. In late 1973, Europe had to choose between supporting Israel and securing Arab oil. Not since the founding of the state of Israel had the choice been so stark. Most countries chose oil."
    ],
    "paragraphTranslations": [
      "1973 年 10 月，理查德·尼克松（Richard Nixon）总统面临着生活成本危机、不断恶化的经济以及接踵而至的法律难题。在 1972 年大选前夕，他曾挑战联邦储备委员会（Federal Reserve）的独立性，施压其主席降低利率。如今，通胀快速攀升，代价随之而来。",
      "紧接着，中东爆发新冲突。埃及和叙利亚入侵以色列，开启了赎罪日战争（Yom Kippur War）。由于阿拉伯产油国实施禁运，抗议美国支持以色列并削减供应，本已剧烈波动的油价随即飙升。",
      "尼克松转而在海外寻找突破口。1974 年辞职前，他实现了美中关系正常化，缓和了与苏联的紧张局势，结束了美国在越南战争中的介入，并派出国务卿亨利·基辛格（Henry Kissinger）维持中东和平。即便尼克松在白宫寓所因服用镇静剂、安眠药和饮酒而精神萎靡、口齿不清，美国的外交机器仍在运转。或许他认为，选民会被其外交成就所吸引，从而忽略他的犯罪行为。\n\n然而，事与愿违。外交政策未能挽救他的支持率，这一数字从 1 月的 68% 跌至 10 月的 30%。中东战火导致能源价格上涨，削弱了美国经济，也让这个本就丑闻缠身的政府失去了民众支持。",
      "当世界权衡美国和以色列袭击伊朗的影响时，重温 1973 年石油冲击的教训至关重要：能源危机演变成难以捉摸的“全方位危机”的速度，往往超过政府的处理能力。起初只是关于油气流向的问题，很快便重塑了美国与世界的关系，并以无人预料的方式深刻影响了日常生活。",
      "考验盟友关系",
      "1973 年，挑战美国经济霸权的新秀是西德和日本。当时有人怀疑，美国炮制这场石油危机是为了减缓这些竞争对手日益强劲的经济增速。由于本周的战争紧随特朗普政府标志性的关税政策动荡而来，中国等现代竞争对手或许也会产生类似怀疑。中国的能源主要依赖煤炭，但其总能源进口中至少有 6% 是通过霍尔木兹海峡（Strait of Hormuz）运输的原油—— 如果战争持续数月而非数周，这足以引发担忧。",
      "欧洲也将陷入困境。特朗普政府曾多次因国防开支、格陵兰岛和贸易问题指责北约盟友。现在，总统又在斥责个别欧洲国家不支持对伊朗的袭击。西班牙因拒绝美国使用其境内的军事基地而被贴上“不配合”的标签；英国则被指责未能继承温斯顿·丘吉尔 （Winston Churchill）的精神遗志。尽管中东仅占欧洲原油进口总量的 5%，但全球性的价格上涨仍会带来刺痛。欧洲各国经济正苦于破纪录的债务和通胀威胁，大西洋两岸盟友关系的残存部分再次面临严峻考验。",
      "基辛格曾将 1973 年定为“欧洲年”，试图修复恶化的关系。但在私下里，他和尼克松对欧洲人的“背信弃义”和“软弱无能”评价极低。 1973 年底，欧洲必须在支持以色列和保障阿拉伯石油之间做选择。自以色列建国以来，选择从未如此残酷。大多数国家最终选择了石油。"
    ],
