    "exerciseChoicePrompt": "Which of the following uses of the underlined word is CLOSEST in meaning to the one in the sentence \"For what it's worth, The Pitt has entirely new ground to cover—the encroachment of AI, the lingering trauma of Covid and, of course, the ongoing US political turmoil that has destabilised an already unwieldy healthcare system.\"?",
